export interface ConnectorConfig {
  /** Slack bot token with chat:write scope. */
  slackBotToken: string
  /** Optional injected fetch for testing. */
  fetch?: typeof fetch
}

export interface TwilioSmsPayload {
  Body: string
  From: string
  MessageSid: string
}

export interface SlackPostMessageResponse {
  ok: boolean
  channel: string
  ts: string
  message: {
    text: string
    username: string
    type: string
    subtype: string
    ts: string
  }
}

export interface HandleResult {
  slackMessageTs: string
  slackChannel: string
  routedTo: 'sales' | 'support'
}

const SALES_KEYWORDS = /pricing|quote|demo/i
const SLACK_API_URL = 'https://slack.com/api/chat.postMessage'

function validatePayload(payload: unknown): asserts payload is TwilioSmsPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  const missing: string[] = []
  if (typeof p.Body !== 'string') missing.push('Body')
  if (typeof p.From !== 'string') missing.push('From')
  if (typeof p.MessageSid !== 'string') missing.push('MessageSid')
  if (missing.length > 0) {
    throw new Error(`Missing required fields: ${missing.join(', ')}`)
  }
}

export async function handle(
  payload: TwilioSmsPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)

  const fetchImpl = config.fetch ?? fetch
  const token = config.slackBotToken

  if (!token) {
    throw new Error('Slack bot token is required (config.slackBotToken)')
  }

  const channel = SALES_KEYWORDS.test(payload.Body) ? '#sales' : '#support'
  const routedTo = channel === '#sales' ? 'sales' : 'support'

  const body = {
    channel,
    text: payload.Body,
    username: payload.From,
    id: payload.MessageSid,
  }

  const response = await fetchImpl(SLACK_API_URL, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    throw new Error(
      `Slack API error: ${response.status} ${response.statusText} for POST ${SLACK_API_URL}`
    )
  }

  const data = (await response.json()) as SlackPostMessageResponse

  if (!data.ok) {
    throw new Error(`Slack API returned ok=false: ${JSON.stringify(data)}`)
  }

  return {
    slackMessageTs: data.ts,
    slackChannel: data.channel,
    routedTo,
  }
}

